const item = $json;
const allocatedKw = Number(item.allocatedKw ?? 5);
const graceThresholdPct = 0.05; // 5% grace band before any charge
const overageKw = Math.max(0, item.measuredKw - allocatedKw);
const overagePct = allocatedKw > 0 ? overageKw / allocatedKw : 0;
const withinGrace = overagePct <= graceThresholdPct;
let tierRate = 0;
if (overagePct > 0.25) tierRate = 450;       // $/kW critical tier
else if (overagePct > 0.10) tierRate = 300;  // $/kW high tier
else if (overagePct > graceThresholdPct) tierRate = 180; // $/kW standard tier
const overageAmount = Math.round(overageKw * tierRate * 100) / 100;
return {
  ...item,
  allocatedKw,
  overageKw,
  overagePct,
  withinGrace,
  tierRate,
  overageAmount,
};

const item = $json;
const overrideAmount = Number(item.data.overrideAmount);
const finalAmount = isFinite(overrideAmount) && overrideAmount >= 0 ? overrideAmount : item.overageAmount;
return { ...item, finalAmount, billingOutcome: 'approved_with_override' };
